<?php
require_once __DIR__ . '/../../config/config.php';require_roles(['ADMIN','HR']);$pdo=db();$id=(int)($_GET['id']??0);$employee=phase2_require_employee($pdo,$id);$departments=$pdo->query('SELECT id,name FROM departments WHERE is_active=1 ORDER BY name')->fetchAll();$positions=$pdo->query('SELECT id,name FROM positions WHERE is_active=1 ORDER BY name')->fetchAll();$branches=$pdo->query('SELECT id,name FROM branches WHERE is_active=1 ORDER BY name')->fetchAll();$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$event=strtoupper(trim((string)$_POST['event_type']));$allowed=['HIRE','ACTIVATE','REGULARIZATION','PROMOTION','TRANSFER','STATUS_CHANGE','RESIGNATION','TERMINATION','REACTIVATION'];$changes=[];if(!in_array($event,$allowed,true))$error='Unsupported lifecycle action.';if(in_array($event,['PROMOTION'],true)&&empty($_POST['position_id']))$error='Select a new position.';if(in_array($event,['TRANSFER'],true)&&empty($_POST['department_id'])&&empty($_POST['branch_id']))$error='Select a new department or branch.';if(!$error){if(!empty($_POST['department_id']))$changes['department_id']=(int)$_POST['department_id'];if(!empty($_POST['position_id']))$changes['position_id']=(int)$_POST['position_id'];if(!empty($_POST['branch_id']))$changes['branch_id']=(int)$_POST['branch_id'];if(!empty($_POST['employment_status']))$changes['employment_status']=$_POST['employment_status'];if($event==='REGULARIZATION'){$changes['employment_status']='Active';$changes['employment_type']='Regular';}if(in_array($event,['HIRE','ACTIVATE','REACTIVATION'],true))$changes['employment_status']='Active';if(in_array($event,['RESIGNATION','TERMINATION'],true))$changes['employment_status']='Separated';try{lifecycle($pdo,$id,$event,$changes,trim((string)$_POST['reason']),valid_date($_POST['effective_date']??'')??date('Y-m-d'));flash('success','Lifecycle action recorded.');redirect('admin/employees/view.php?id='.$id);}catch(Throwable $exception){$error='The lifecycle action could not be completed and was rolled back.';}}}
$pageTitle='Employee lifecycle';require __DIR__.'/../../includes/header.php';?><div class="mb-7"><a href="view.php?id=<?=$id?>" class="text-sm font-bold text-teal-700">← Employee profile</a><h1 class="font-display text-3xl font-bold mt-2">Employee lifecycle</h1><p class="text-slate-500"><?=e($employee['first_name'].' '.$employee['last_name'])?> · Current status: <?=e($employee['employment_status'])?></p></div><?php if($error):?><div class="mb-5 rounded-lg bg-red-50 border border-red-200 p-3 text-sm text-red-700"><?=e($error)?></div><?php endif;?><form method="post" class="bg-white border border-slate-200 rounded-xl p-6 max-w-3xl"><?= csrf_field() ?><div class="grid md:grid-cols-2 gap-5"><label class="text-sm font-semibold">Action<select name="event_type" class="field"><?php foreach(['HIRE','ACTIVATE','REGULARIZATION','PROMOTION','TRANSFER','STATUS_CHANGE','RESIGNATION','TERMINATION','REACTIVATION'] as $v):?><option><?=e($v)?></option><?php endforeach;?></select></label><label class="text-sm font-semibold">Effective date<input required type="date" name="effective_date" value="<?=date('Y-m-d')?>" class="field"></label><label class="text-sm font-semibold">New department<select name="department_id" class="field"><option value="">No change</option><?php foreach($departments as $v):?><option value="<?=$v['id']?>"><?=e($v['name'])?></option><?php endforeach;?></select></label><label class="text-sm font-semibold">New position<select name="position_id" class="field"><option value="">No change</option><?php foreach($positions as $v):?><option value="<?=$v['id']?>"><?=e($v['name'])?></option><?php endforeach;?></select></label><label class="text-sm font-semibold">New branch<select name="branch_id" class="field"><option value="">No change</option><?php foreach($branches as $v):?><option value="<?=$v['id']?>"><?=e($v['name'])?></option><?php endforeach;?></select></label><label class="text-sm font-semibold">New status<select name="employment_status" class="field"><option value="">Automatic/action default</option><?php foreach(['Active','Probationary','On Leave','Separated'] as $v):?><option><?=e($v)?></option><?php endforeach;?></select></label><label class="md:col-span-2 text-sm font-semibold">Reason<textarea required name="reason" rows="4" class="field"></textarea></label></div><button class="mt-6 rounded-lg bg-teal-700 px-5 py-3 text-sm font-bold text-white">Apply lifecycle action</button></form><?php require __DIR__.'/../../includes/footer.php';